const uint8_t* font5x7_get_glyph (char ch) {
	uint8_t index;
	if (ch == ' ') {
		index = 0;
	} else if (ch >= '0' && ch <= '9') {
		index = 1 + (uint8_t) (ch - '0');
	} else if (ch >= 'A' && ch <= 'Z') {
		index = 11 + (uint8_t) (ch - 'A');
	} else if (ch >= 'a' && ch <= 'z') {
		index = 37 + (uint8_t) (ch - 'a');
	} else {
		return NULL;
	}
	return font5x7[index];
}
